#include<bits/stdc++.h>
/*
#include<windows.h>
*/
using namespace std;
using ll=long long;
using pii=pair<int,int>;
int n;
ll m;
vector<ll>a,b,fa;
bool check(ll mid){
	int len=n-(upper_bound(fa.begin(),fa.end(),-mid)-fa.begin())+1;
	return mid*len-b[len-1]<=m;
}
int main(){
	freopen("crystal.in","r",stdin);
	freopen("crystal.out","w",stdout);
//	freopen("crystal.in","r",stdin);
//	freopen("crystal.out","w",stdout);
	cin>>n>>m;
	a.resize(n);
	b.resize(n);
	fa.resize(n);
	for(int i=0;i<n;i++){
		cin>>a[i];
	}
	sort(a.begin(),a.end());
	b[0]=a[0];
	fa[0]=-a[n-1];
	for(int i=1;i<n;i++){
		b[i]=a[i]+b[i-1];
		fa[i]=-a[n-i-1];
	}
	ll l=a[0],r=a[n-1],mid;
	while(l<r){
		mid=(l+r+1)/2;
		if(check(mid))l=mid;
		else r=mid-1;
	}
	cout<<n-(upper_bound(fa.begin(),fa.end(),-r)-fa.begin())+1<<endl;
	return 0;
}
